-- Identity and tenancy schema (feature 001, FR-001-001, FR-001-007).
--
-- Tenant isolation is enforced twice: the application filters every statement by tenant_id, and
-- the schema rejects cross-tenant references through composite (tenant_id, id) foreign keys, so a
-- bug or a bypassed application layer still cannot link rows of different tenants.
--
-- IDs are generated by the application (UUIDv7); no database defaults are relied upon.

CREATE TABLE tenants (
    id         uuid        PRIMARY KEY,
    slug       text        NOT NULL,
    created_at timestamptz NOT NULL,
    CONSTRAINT tenants_slug_uniq   UNIQUE (slug),
    CONSTRAINT tenants_slug_format CHECK (slug ~ '^[a-z][a-z0-9-]{1,61}[a-z0-9]$' AND slug !~ '--')
);

CREATE TABLE workspaces (
    id         uuid        PRIMARY KEY,
    tenant_id  uuid        NOT NULL REFERENCES tenants (id),
    slug       text        NOT NULL,
    created_at timestamptz NOT NULL,
    -- Target of composite foreign keys from tenant-scoped children.
    CONSTRAINT workspaces_tenant_id_uniq   UNIQUE (tenant_id, id),
    CONSTRAINT workspaces_tenant_slug_uniq UNIQUE (tenant_id, slug),
    CONSTRAINT workspaces_slug_format      CHECK (slug ~ '^[a-z][a-z0-9-]{1,61}[a-z0-9]$' AND slug !~ '--')
);

CREATE TABLE namespaces (
    id           uuid        PRIMARY KEY,
    tenant_id    uuid        NOT NULL REFERENCES tenants (id),
    workspace_id uuid        NOT NULL,
    slug         text        NOT NULL,
    environment  text        NOT NULL,
    created_at   timestamptz NOT NULL,
    CONSTRAINT namespaces_tenant_id_uniq     UNIQUE (tenant_id, id),
    -- A namespace is addressed by name alone inside its tenant (see OpenAPI Namespace header).
    CONSTRAINT namespaces_tenant_slug_uniq   UNIQUE (tenant_id, slug),
    CONSTRAINT namespaces_slug_format        CHECK (slug ~ '^[a-z][a-z0-9-]{1,61}[a-z0-9]$' AND slug !~ '--'),
    CONSTRAINT namespaces_environment_valid  CHECK (environment IN ('dev', 'staging', 'prod')),
    -- The workspace must belong to the SAME tenant as the namespace.
    CONSTRAINT namespaces_workspace_same_tenant_fk
        FOREIGN KEY (tenant_id, workspace_id) REFERENCES workspaces (tenant_id, id)
);

CREATE TABLE memberships (
    tenant_id  uuid        NOT NULL REFERENCES tenants (id),
    subject    text        NOT NULL,
    role       text        NOT NULL,
    created_at timestamptz NOT NULL,
    PRIMARY KEY (tenant_id, subject),
    CONSTRAINT memberships_subject_valid CHECK (char_length(subject) BETWEEN 1 AND 255 AND subject !~ '[[:cntrl:]]'),
    CONSTRAINT memberships_role_valid    CHECK (role IN ('admin', 'developer', 'operator', 'viewer'))
);

CREATE TABLE audit_records (
    id            uuid        PRIMARY KEY,
    tenant_id     uuid        NOT NULL REFERENCES tenants (id),
    actor         text        NOT NULL,
    action        text        NOT NULL,
    resource_type text        NOT NULL,
    resource_id   text        NOT NULL,
    reason        text,
    trace_id      text,
    created_at    timestamptz NOT NULL,
    CONSTRAINT audit_records_trace_id_format CHECK (trace_id IS NULL OR trace_id ~ '^[0-9a-f]{32}$')
);

CREATE INDEX audit_records_tenant_created_idx ON audit_records (tenant_id, created_at DESC, id DESC);

-- The audit trail is append-only: rows can never be rewritten or removed by the application role.
CREATE FUNCTION audit_records_reject_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit_records is append-only (% attempted)', TG_OP
        USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER audit_records_append_only
    BEFORE UPDATE OR DELETE ON audit_records
    FOR EACH ROW EXECUTE FUNCTION audit_records_reject_mutation();

CREATE TRIGGER audit_records_no_truncate
    BEFORE TRUNCATE ON audit_records
    FOR EACH STATEMENT EXECUTE FUNCTION audit_records_reject_mutation();
